          <input type="tel" id="em_phone" placeholder="Enter 10-digit mobile number" required pattern="[0-9]{10}" style="width: 100%; padding: 12px 14px; border-radius: 12px; border: 1.5px solid #E2E8F0; font-size: 14px; color: #0F172A; background: #F8FAFC; outline: none; box-sizing: border-box;">
